export function t(key, ...args) {
  const e = D[key];
  if (!e) return key;
  let s = e[S.lang === 'ru' ? 1 : 0];
  for (let i = 0; i < args.length; i++) s = s.replace('{' + i + '}', args[i]);
  return s;
}
export const hasKey = k => !!D[k];
